def validate(obj,s,path='study'):
 typ=s.get('type')
 if typ:
  cls={'object':dict,'array':list,'string':str,'boolean':bool,'integer':int,'number':(int,float)}[typ]
  assert isinstance(obj,cls),(path,typ)
 if 'enum' in s:assert obj in s['enum'],path
 if 'const' in s:assert obj==s['const'],path
 if isinstance(obj,str):assert len(obj)>=s.get('minLength',0),path
 if isinstance(obj,list):
  assert len(obj)>=s.get('minItems',0),path
  for i,x in enumerate(obj):validate(x,s.get('items',{}),path+'.'+str(i))
 if isinstance(obj,dict):
  assert set(s.get('required',[]))<=set(obj),(path,'required')
  props=s.get('properties',{})
  if s.get('additionalProperties') is False:assert set(obj)<=set(props),(path,'unexpected')
  for k,v in obj.items():
   if k in props:validate(v,props[k],path+'.'+k)
validate(p['study'],r['study_schema'])
assert p['parent_trial'] in r['context']['allowed_observation_ids']
assert set(p['study']['evidence_refs'])<=set(r['context']['allowed_observation_ids'])
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
assert r['context']['previous_runtime_error'] is None
