assert any(v['role']=='candidate' for v in p['variants'])
assert len({v['name'] for v in p['variants']})==len(p['variants'])
assert len({v['file'] for v in p['variants']})==len(p['variants'])
checks['proposal_schema_and_refs']='Passed all constructs of supplied study JSON schema using stdlib; all local evidence/parent/protocol refs valid; no previous runtime error exposed.'
def model(tree):return next(n for n in tree.body if isinstance(n,ast.ClassDef) and n.name=='Model')
def methods(tree):return {n.name:n for n in model(tree).body if isinstance(n,ast.FunctionDef)}
def strip_doc(node):
 node=copy.deepcopy(node)
 if node.body and isinstance(node.body[0],ast.Expr) and isinstance(node.body[0].value,ast.Constant) and isinstance(node.body[0].value.value,str):node.body=node.body[1:]
 return node
class RemoveRadiusSwitch(ast.NodeTransformer):
 def visit_If(self,node):
  names=[n.id for n in ast.walk(node.test) if isinstance(n,ast.Name)]
  attrs=[n.attr for n in ast.walk(node.test) if isinstance(n,ast.Attribute)]
  if 'summary_radius_source' in names or 'summary_radius_source' in attrs:return None
  return self.generic_visit(node)
 def visit_Assign(self,node):
  if any(isinstance(n,ast.Attribute) and n.attr=='summary_radius_source' for t in node.targets for n in ast.walk(t)):return None
  return self.generic_visit(node)
 def visit_FunctionDef(self,node):
  node=self.generic_visit(node)
  if node.name=='__init__':
   args=node.args.args; start=len(args)-len(node.args.defaults)
   pairs=[(a,node.args.defaults[i-start] if i>=start else None) for i,a in enumerate(args)]
   pairs=[(a,d) for a,d in pairs if a.arg"'!='"'summary_radius_source']
   node.args.args=[a for a,d in pairs];node.args.defaults=[d for a,d in pairs if d is not None]
  return node
normalized=[];hashes={}
for v in p['variants']:
 file=v['file'];assert Path(file).name==file and file.endswith('.py')
 source=Path(file).read_text();tree=ast.parse(source);compile(source,file,'exec')
 cfg=ast.literal_eval(next(n.value for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets)))
 assert cfg==v['config']
 ctor=methods(tree)['__init__'];defaults=dict(zip([a.arg for a in ctor.args.args][-len(ctor.args.defaults):],ctor.args.defaults))
 for k,val in cfg.items():
  got=ast.literal_eval(defaults[k]);assert (list(got) if isinstance(got,tuple) else got)==val,(file,k,got,val)
 oldfile='history_g1_r0051_match_nomean_'+('click' if cfg['summary_rotation_partition']=='click' else 'shift')+'_'+cfg['residual_routing']+'.py'
 old=ast.parse(Path(oldfile).read_text());new_methods=methods(tree);old_methods=methods(old)
 assert new_methods.keys()==old_methods.keys()
 for name,method in new_methods.items():
  modified=RemoveRadiusSwitch().visit(strip_doc(method))
  assert ast.dump(modified)==ast.dump(strip_doc(old_methods[name])),(file,name)
 # All import roots remain authorized; the new code adds no call except ones_like.
 assert {(n.module or '').split('.')[0] for n in tree.body if isinstance(n,ast.ImportFrom)}<={'torch','unirank'}
 assert {a.name.split('.')[0] for n in tree.body if isinstance(n,ast.Import) for a in n.names}<={'torch'}
 forbidden={'open','eval','exec','compile','__import__','load','save','read','write','system','popen','subprocess'}
 for n in ast.walk(tree):
  if isinstance(n,ast.Call):
   call=n.func.id if isinstance(n.func,ast.Name) else n.func.attr if isinstance(n.func,ast.Attribute) else ''
   assert call not in forbidden,(file,call)
 hashes[file]=hashlib.sha256(source.encode()).hexdigest()
 normalized.append(ast.dump(strip_doc(new_methods['_history_stratified_summary_values'])))
assert len(set(normalized))==1
checks['model_syntax_config_defaults_imports_IO']='Passed for four standalone files; CONFIG equals submitted configs/defaults after normalizing tuple/list widths; only allowed imports and no direct filesystem/network/dynamic execution calls.'
checks['adaptive_mode_source_bridge']='For all four counterparts, removing only radius-source argument/guards/attribute and unit override produces AST-identical constructors and helper bodies after ignoring docstrings/comments. Every other method is AST-identical without any removal. This is source parity, not executed tensor parity.'
checks['module_capacity_and_rng']='Constructor bridge preserves exact learned-module construction, reset order and forked RNG; no new parameter, buffer, module or random operation. Expected parameter counts are inherited, awaiting host measurement.'
checks['factorial_helpers']='All four helper bodies identical; cells differ only literal CONFIG and declared placement/routing defaults.'
checks['module_sha256']=hashes
checks['limits']='No torch import, tensor/autograd/BF16 validation, raw-data checksum rerun, new training, scoring, installations or held-out access. Authorized tools expose resolve/read/search only; no writable memory or diagnostics interface was invented.'
print(json.dumps(checks,indent=2))
p['study']['inherited_components'].append('Trajectory review: total action erasure/context replacement at r0024 fell near0.641 versus0.66675 incumbent; value-only r0025 retained0.666244 while scorer-only r0025 fell to0.654174. Match-only summary branch r0027 was0.651463; restoring pools improved later branches. Stopped observed-vs-item-duplicate r0037 gave0.666169 vs0.663624. r0045 residual-click0.664247 versus residual-shift0.666017 reversed the mean placement direction. r0048 fixed-direction real0.665989 exceeded shift0.663776; opposite-radius real r0049 fell to0.664244; paired-RMS r0050 restored0.665893. r0051 removing common mean changed task real by+0.00006693 and task shifted by-0.00011395 versus r0050, not exact empirical invariance. These are lower-performing or diagnostic trajectories, not independent repeats or proof of a unique explanation; all exposed trial statuses succeeded and no runtime failure is currently reported.')
for v in p['variants']:
 v['note']+=' Preparation validation: '+json.dumps(checks,sort_keys=True)+'. Host preflight before interpreting mechanism: run source-adaptive parity against its r0051 counterpart at common weights and fixed seed; verify finite forward/backward and all four probability shapes under frozen precision; check empty/single-group and noncontiguous masks, padding/target-action invariance, and helper/match-action rows0/4 invariance to finite action-vector perturbations at fixed membership in unit mode. Full-model action invariance is not expected. Record FP32/BF16 deviations, counts and failures; do not modify host precision. If diagnostics are not exposed, report attribution as provisional. Prospective observations and revisions stay in this authorized proposal; read-only evidence and human-owned knowledge were not modified.'
Path('proposal.json').write_text(json.dumps(p,indent=2)+'\\n')
